// The 3 known provider-parent Drive folders every client root folder lives
// directly inside -- same constants used in the orchestrator's
// 'Combine Gmail & Outlook Per Client' node.
return [
  { json: { parentFolderId: '1-1EdTSWeoFPnbRa_hKdYsX4aMnqiQSSE', provider: 'gmail-only' } },
  { json: { parentFolderId: '1L5xu6tTaS6yZXbHpTrpE4IQ1xjV8G_J8', provider: 'outlook-only' } },
  { json: { parentFolderId: '102oeld1yMYGMmWs2Od198HqO1KeVhv_n', provider: 'combined' } },
];

// Defensive -- these parent folders should only ever contain client root
// folders, but filter out anything that isn't actually a folder just in case.
return $input.all().filter(item => item.json.mimeType === 'application/vnd.google-apps.folder');

// Exact match on name -- same pattern used throughout the orchestrator.
// Client folders with no conversation sheet yet produce no output here,
// which is correct: nothing to sort for them.
const exact = $input.all().find(item => (item.json.name || '').toString().trim().toLowerCase() === 'conversation');
return exact ? [{ json: { id: exact.json.id, name: exact.json.name } }] : [];

// Every conversation sheet has exactly one tab, with a randomly-generated
// gid and an inconsistent name across different sheets -- same reason the
// Processor workflows resolve this at runtime instead of hardcoding it.
const spreadsheetId = $('Pick Exact Conversation Sheet Match').item.json.id;
const props = $json.sheets?.[0]?.properties;
if (!props?.title || props.sheetId === undefined) {
  throw new Error(`Could not resolve tab name/sheetId for conversation sheet ${spreadsheetId}`);
}
return [{ json: { spreadsheetId, tabName: props.title, tabSheetId: props.sheetId } }];

// Find which column is literally named 'timestamp' and use its position
// directly as the sort dimension -- header layout can vary slightly across
// sheets (some are older, from before recent fixes), so this is looked up
// per sheet rather than assumed to be a fixed position.
const { spreadsheetId, tabName, tabSheetId } = $('Extract Tab Info').item.json;
const headerRow = $json.values?.[0] || [];
const idx = headerRow.findIndex(h => (h || '').toString().trim().toLowerCase() === 'timestamp');

return [{
  json: {
    spreadsheetId,
    tabName,
    tabSheetId,
    hasTimestampColumn: idx !== -1,
    timestampColumnIndex: idx
  }
}];
